function validate(input) {
  const [init, calls] = input;
  if (!Number.isInteger(init) || init < -1000 || init > 1000) return 'init must be an integer from -1000 to 1000.';
  if (!Array.isArray(calls) || calls.length > 1000) return 'Give at most 1000 calls.';
  if (calls.some((call) => !['increment', 'decrement', 'reset'].includes(call))) return 'Each call must be "increment", "decrement" or "reset".';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [init, calls] = input, results = [];
  const counter = solve(init);
  if (!counter || typeof counter !== 'object') throw new Error('createCounter must return an object.');
  for (const name of calls) {
    if (typeof counter[name] !== 'function') throw new Error(`The counter has no ${name} function.`);
    const value = counter[name]();
    if (typeof value !== 'number') throw new Error(`${name}() must return a number.`);
    kit.trace(`counter.${name}() returns ${value}`);
    results.push(value);
  }
  return results;
}

