function createCounter(init) {
  // Keep every call and replay them all from init each time.
  const history = [];
  const replay = () => {
    let value = init;
    for (const call of history) {
      if (call === 'reset') value = init;
      else value += call === 'increment' ? 1 : -1;
    }
    return value;
  };
  const record = (call) => {
    history.push(call);
    return replay();
  };
  return {
    increment: () => record('increment'),
    decrement: () => record('decrement'),
    reset: () => record('reset'),
  };
}

