function generate(rand, size) {
  const edges = [-1000, -1, 0, 1, 1000];
  const init = rand() < 0.3 ? edges[Math.floor(rand() * edges.length)] : Math.floor(rand() * 2001) - 1000;
  const count = size === 'small' ? Math.floor(rand() * 9) : 1000;
  // Lean towards one direction now and then, so long runs drift far from init.
  const bias = rand();
  const calls = Array.from({ length: count }, () => {
    const roll = rand();
    if (roll < 0.1) return 'reset';
    return roll < 0.1 + 0.9 * bias ? 'increment' : 'decrement';
  });
  return [init, calls];
}
